    scrollColumnToValue(yearCol, year, false);
    scrollColumnToValue(monthCol, month, false);
    scrollColumnToValue(dayCol, day, false);
    wireWheelColumn(yearCol, 'year');
    wireWheelColumn(monthCol, 'month');
    wireWheelColumn(dayCol, 'day');

